def get_number(prompt):
    """Get a number from user input."""
    while True:
        try:
            num = float(input(prompt))
            return num
        except ValueError:
            print("That's not a valid number. Please try again.")

def get_operation():
    """Get an operation from user input."""
    operations = {"+": add, "-": subtract, "*": multiply, "/": divide}
    while True:
        operation = input("Enter an operation (+, -, *, /): ").lower()
        if operation in operations:
            return operations[operation]
        else:
            print("That's not a valid operation. Please try again.")

def perform_operation(num1, num2, operation):
    """Perform an arithmetic operation on two numbers."""
    return operation(num1, num2)

def add(num1, num2):
    """Perform addition on two numbers."""
    return num1 + num2

def subtract(num1, num2):
    """Perform subtraction on two numbers."""
    return num1 - num2

def multiply(num1, num2):
    """Perform multiplication on two numbers."""
    return num1 * num2

def divide(num1, num2):
